from pathlib import Path
import json
r=Path(__file__).resolve().parent
changes=json.loads('{"site/app.js": [["/* ---------- Today ---------- */", "function approvedUnscheduled(l){const p=TL.simpleSummary(l);return TL.isOpen(l)&&p.approved&&!p.scheduled;}\\n\\n/* ---------- Today ---------- */"], ["approved=open.filter(l=>TL.simpleSummary(l).approved)", "approved=open.filter(approvedUnscheduled)"], ["data-approval=\\"approved\\" data-view=\\"open\\"><small>Approved</small>", "data-approval=\\"approved\\" data-view=\\"approved-unscheduled\\"><small>Approved</small>"], ["view===\'overdue-movein\'?TL.simpleSummary(l).moveInOverdue:", "view===\'approved-unscheduled\'?approvedUnscheduled(l):view===\'overdue-movein\'?TL.simpleSummary(l).moveInOverdue:"], ["...(view===\'overdue-movein\'?[[\'overdue-movein\',\'Overdue move-ins\']]:[])", "...(view===\'approved-unscheduled\'?[[\'approved-unscheduled\',\'Approved\']]:[]),...(view===\'overdue-movein\'?[[\'overdue-movein\',\'Overdue move-ins\']]:[])"], ["if(a===\'simpleView\'){UI.q=\'\';UI.moveView=", "if(a===\'simpleView\'){UI.leadMaker=\'all\';UI.q=\'\';UI.moveView="]]}')
for name,edits in changes.items():
 p=r/name;s=p.read_text()
 for old,new in edits:
  if s.count(old)!=1: raise SystemExit(f"Unexpected approved filter source in {name}")
  s=s.replace(old,new,1)
 p.write_text(s)
p=r/"test/simple-referrals.test.mjs"
p.write_text(p.read_text()+'\ntest(\'homepage approved count and destination exclude scheduled, overdue, moved and lost referrals\',()=>{\n const ctx=uiContext(),tl=ctx.TL,{UI,V,filtered}=ctx.simpleTest,base=tl.S.leads[0];\n const cases=[[\'unscheduled\',\'new\',\'missing\',null,\'none\'],[\'future\',\'new\',\'missing\',tl.addDays(10),\'scheduled\'],[\'overdue\',\'new\',\'received\',tl.addDays(-3),\'scheduled\'],[\'moved\',\'movein\',\'received\',tl.addDays(-1),\'moved\'],[\'lost\',\'lost\',\'missing\',null,\'none\'],[\'pending\',\'new\',\'waiting\',null,\'none\'],[\'legacy\',\'new\',\'missing\',tl.addDays(4),null]];\n tl.S.leads=cases.map(([id,stage,approval,moveIn,moveStatus])=>({...JSON.parse(JSON.stringify(base)),id,first:\'Synthetic\',last:id,stage,moveIn,referralProgress:{programKey:[base.payer,base.building].join(\'|\'),approval,assessment:\'pending\',paperworkReceived:approval===\'received\',...(moveStatus?{moveStatus}:{}),due:tl.T,note:\'\'}}));\n const home=V.today(),button=home.match(/<button[^>]*data-approval="approved"[^>]*>[\\s\\S]*?<\\/button>/)[0];\n assert.match(button,/data-view="approved-unscheduled"/);assert.match(button,/<b>1<\\/b>/);assert.match(button,/Set a move-in date/);\n UI.moveView=button.match(/data-view="([^"]+)"/)[1];UI.simpleApproval=\'approved\';\n assert.deepEqual(Array.from(filtered(),l=>l.id),[\'unscheduled\']);assert.match(V.leads(),/Approved/);\n UI.moveView=\'upcoming\';assert.deepEqual(Array.from(filtered(),l=>l.id).sort(),[\'future\',\'legacy\',\'overdue\']);\n UI.moveView=\'open\';assert.deepEqual(Array.from(filtered(),l=>l.id).sort(),[\'future\',\'legacy\',\'overdue\',\'unscheduled\']);\n});\n')
